INSERT INTO public.questions (public_id, created_at, updated_at, deleted, audio_prompt_ref, author_user_public_id, availability_flags_explicit, available_for_exam, available_for_practice, correct_answer_text, is_current, ever_published, image_prompt_ref, max_word_count, min_word_count, pool, prompt_text, pte_task_type, reference_answer_text, rejection_reason, revision_group_public_id, revision_number, status, supersedes_public_id, task_type_key, task_type_section, tenant_id, title, version, visibility) VALUES ('2156fc04-502e-4dd6-80ad-0f13be763f11','2026-10-28 16:07:11.820294+00','2026-10-28 16:07:11.83137+00',false,'92666322-bfdc-4275-b0dc-46bbf9e9d559',(SELECT public_id FROM public.users WHERE username = 'admin@local.com'),'t','t','f',NULL,'t','t',NULL,NULL,NULL,'EXAM',NULL,'RE_TELL_LECTURE','So there are two theories for how the gas giants formed. One is the same theory I showed you just now core accretion, right. And the other is called disk instability and one of our colleagues at DTM has done a lot of work on that and so it''s unclear exactly how they formed but you''re right what we''re trying to do the reason we''re trying to get the higher and higher pressure in the lab is because we are trying to understand more about the pressure inside the gas giants. It''s thought that the gas giants also have a metallic core, but maybe the metallic core not made of iron. Hydrogen, for example becomes metallic at a certain pressure. So it''s very possible that the insides of these planets could have metallic cores, could have hydrogen cores, could have rocky portions we''re not sure. But the higher pressure we can get in the lab, the closer we can get understanding the interiors of the gas giants and the exoplanet that are so big.',NULL,'523cb72b-3251-4911-8a7a-ae8ad2b7389c','1','APPROVED',NULL,'RE_TELL_LECTURE','SPEAKING',NULL,'DOC22 RE_TELL_LECTURE a468e68edeae08bc | Gas Giants','1','SHARED') ON CONFLICT (public_id) DO NOTHING;
INSERT INTO public.questions (public_id, created_at, updated_at, deleted, audio_prompt_ref, author_user_public_id, availability_flags_explicit, available_for_exam, available_for_practice, correct_answer_text, is_current, ever_published, image_prompt_ref, max_word_count, min_word_count, pool, prompt_text, pte_task_type, reference_answer_text, rejection_reason, revision_group_public_id, revision_number, status, supersedes_public_id, task_type_key, task_type_section, tenant_id, title, version, visibility) VALUES ('575d6615-d72c-4f38-8cb8-c03305e1d0cc','2026-10-28 16:07:12.829871+00','2026-10-28 16:07:12.840791+00',false,'e9598b12-1ca3-43e5-88c4-6e25da77c46b',(SELECT public_id FROM public.users WHERE username = 'admin@local.com'),'t','t','f',NULL,'t','t',NULL,NULL,NULL,'EXAM',NULL,'RE_TELL_LECTURE','Hello everyone. Today''s lecture is about setting up a website. I''m going to be focusing on things that you need to consider to ensure your website really adds value to the people using it.
INSERT INTO public.questions (public_id, created_at, updated_at, deleted, audio_prompt_ref, author_user_public_id, availability_flags_explicit, available_for_exam, available_for_practice, correct_answer_text, is_current, ever_published, image_prompt_ref, max_word_count, min_word_count, pool, prompt_text, pte_task_type, reference_answer_text, rejection_reason, revision_group_public_id, revision_number, status, supersedes_public_id, task_type_key, task_type_section, tenant_id, title, version, visibility) VALUES ('5a8c4747-5192-49e7-840a-f03f56e41c98','2026-10-28 16:07:14.317096+00','2026-10-28 16:07:14.331747+00',false,'0ada5492-dcab-4551-a7cb-e49d6cbc1acd',(SELECT public_id FROM public.users WHERE username = 'admin@local.com'),'t','t','f',NULL,'t','t',NULL,NULL,NULL,'EXAM',NULL,'RE_TELL_LECTURE','Super-symmetry is a mathematical idea that people have developed an effort to understand the sharpest organising principle for the fundamental constituents of matter. You see, we have learned that particles that seem to be different, can actually secretly be united by certain symmetry principles. So we use the fact that there are symmetric objects in the world like a sphere or basketball. You turn a sphere, and even though you''ve transformed it, it looks the same fundamentally. We found that certain particles when you transform one particle into another, even though looks like the identity of the particle has changed, overall the equations describing it they don''t change at all at an underlying level of symmetry, but we''ve not been able to do is find a symmetry that would relate certain kinds of particles, namely matter particles and force particles. Matter particles are particles like electrons, muons and quarks, force particles are like photons and gluons and WZ bosons. Super-symmetry is a symmetry that actually relates to these two kinds, these two classes of particles. And people have proven that super-symmetry is the last possible symmetry of the fundamental particles that are mathematics, reality has not yet been shown to make use of it. So people are now trying to see whether that symmetry might actually be working in the world can be found evidence for it in our understanding of fundamental particles.',NULL,'16b0d895-d27c-4373-8a84-524531bbdd01','1','APPROVED',NULL,'RE_TELL_LECTURE','SPEAKING',NULL,'DOC22 RE_TELL_LECTURE e520c9870f0a1e43 | Super-symmetry','1','SHARED') ON CONFLICT (public_id) DO NOTHING;
INSERT INTO public.questions (public_id, created_at, updated_at, deleted, audio_prompt_ref, author_user_public_id, availability_flags_explicit, available_for_exam, available_for_practice, correct_answer_text, is_current, ever_published, image_prompt_ref, max_word_count, min_word_count, pool, prompt_text, pte_task_type, reference_answer_text, rejection_reason, revision_group_public_id, revision_number, status, supersedes_public_id, task_type_key, task_type_section, tenant_id, title, version, visibility) VALUES ('978188ff-02f8-4b9b-8c8a-31c875a4c62f','2026-10-28 16:07:15.301401+00','2026-10-28 16:07:15.314488+00',false,'bc9d7e3f-2806-444d-8c37-0985a1a939ed',(SELECT public_id FROM public.users WHERE username = 'admin@local.com'),'t','t','f','Source / birthplace / origin','t','t',NULL,NULL,NULL,'EXAM','What is the word for the place where a river starts?','ANSWER_SHORT_QUESTION',NULL,NULL,'872c67df-7e3c-47b2-bbdb-8e05e56853de','1','APPROVED',NULL,'ANSWER_SHORT_QUESTION','SPEAKING',NULL,'DOC22 ANSWER_SHORT_QUESTION 4ee6410997b3208e | ASQ','1','SHARED') ON CONFLICT (public_id) DO NOTHING;
