INSERT INTO public.questions (public_id, created_at, updated_at, deleted, audio_prompt_ref, author_user_public_id, availability_flags_explicit, available_for_exam, available_for_practice, correct_answer_text, is_current, ever_published, image_prompt_ref, max_word_count, min_word_count, pool, prompt_text, pte_task_type, reference_answer_text, rejection_reason, revision_group_public_id, revision_number, status, supersedes_public_id, task_type_key, task_type_section, tenant_id, title, version, visibility) VALUES ('4ed21e71-2847-4d36-80cc-ce8f449c5a62','2026-10-28 16:07:21.164896+00','2026-10-28 16:07:21.173982+00',false,'93f16e83-eba4-4237-8b56-130b6be25dcb',(SELECT public_id FROM public.users WHERE username = 'admin@local.com'),'t','t','f',NULL,'t','t',NULL,NULL,NULL,'EXAM','The speakers discuss the growing trend towards eco-tourism holidays and whether they really protect the environment and local cultures.','SUMMARIZE_GROUP_DISCUSSION','This lecture mainly talks about eco-tourism holidays. Firstly, the speaker emphasizes nowadays there is an increasing trend towards eco-tourism holidays. Also, he mentions the tourism should not only protect but also actively improve our environment and its cultures. Lastly, the speaker believes travelers can make the right choice when confronted with this type of marketing. In conclusion, this lecture is very informative.',NULL,'e0ad0ee5-3013-41e0-8294-61d9db88e626','1','APPROVED',NULL,'SUMMARIZE_GROUP_DISCUSSION','SPEAKING',NULL,'DOC22 SUMMARIZE_GROUP_DISCUSSION fa1ff5bf92a3bed8 | [MOCK] Eco-tourism','1','SHARED') ON CONFLICT (public_id) DO NOTHING;
INSERT INTO public.questions (public_id, created_at, updated_at, deleted, audio_prompt_ref, author_user_public_id, availability_flags_explicit, available_for_exam, available_for_practice, correct_answer_text, is_current, ever_published, image_prompt_ref, max_word_count, min_word_count, pool, prompt_text, pte_task_type, reference_answer_text, rejection_reason, revision_group_public_id, revision_number, status, supersedes_public_id, task_type_key, task_type_section, tenant_id, title, version, visibility) VALUES ('e25d018d-dcac-4ff2-901d-511ca3a6c224','2026-10-28 16:07:22.406227+00','2026-10-28 16:07:22.418037+00',false,'7498a956-b96e-409e-ab32-0e7a9dfd0e07',(SELECT public_id FROM public.users WHERE username = 'admin@local.com'),'t','t','f',NULL,'t','t',NULL,NULL,NULL,'EXAM','The speakers discuss the evidence that climate change is the result of human activities since the industrial revolution.','SUMMARIZE_GROUP_DISCUSSION','Climate change is a result of human activities, as our own actions are causing a genuine threat. To be more specific, land and sea temperatures started to increase around 200 years ago, when the industrial revolution began. This has resulted in the production of harmful gases, which is the proof of the damaging effect of our actions.',NULL,'a62051b5-8697-426d-bcd0-cd1544944519','1','APPROVED',NULL,'SUMMARIZE_GROUP_DISCUSSION','SPEAKING',NULL,'DOC22 SUMMARIZE_GROUP_DISCUSSION 0ce4a5f064cfb118 | [MOCK] Climate Change','1','SHARED') ON CONFLICT (public_id) DO NOTHING;
INSERT INTO public.questions (public_id, created_at, updated_at, deleted, audio_prompt_ref, author_user_public_id, availability_flags_explicit, available_for_exam, available_for_practice, correct_answer_text, is_current, ever_published, image_prompt_ref, max_word_count, min_word_count, pool, prompt_text, pte_task_type, reference_answer_text, rejection_reason, revision_group_public_id, revision_number, status, supersedes_public_id, task_type_key, task_type_section, tenant_id, title, version, visibility) VALUES ('58a21bae-c28c-4844-b9bb-2c8fb733bc04','2026-10-28 16:07:23.369195+00','2026-10-28 16:07:23.379479+00',false,'e3570e93-c39b-45ed-8851-96f93e762670',(SELECT public_id FROM public.users WHERE username = 'admin@local.com'),'t','t','f',NULL,'t','t',NULL,NULL,NULL,'EXAM','The speakers discuss why allergies are becoming more common and how people who suffer from them can be treated.','SUMMARIZE_GROUP_DISCUSSION','Allergies seem to be increasing these days especially in more hygienic societies where children are less exposed to harmful situations at an early age. They are a result of the body''s immune system reacting to something it believes is harmful and producing histamines to get rid the body of this. Sufferers are advised to avoid the trigger for their allergy. When this is impossible, they can be prescribed anti-histamines.',NULL,'12fdc9b6-f37d-457c-b3ef-bdd39e0e8212','1','APPROVED',NULL,'SUMMARIZE_GROUP_DISCUSSION','SPEAKING',NULL,'DOC22 SUMMARIZE_GROUP_DISCUSSION f441ab2f47600db9 | [MOCK] Allergies','1','SHARED') ON CONFLICT (public_id) DO NOTHING;
INSERT INTO public.questions (public_id, created_at, updated_at, deleted, audio_prompt_ref, author_user_public_id, availability_flags_explicit, available_for_exam, available_for_practice, correct_answer_text, is_current, ever_published, image_prompt_ref, max_word_count, min_word_count, pool, prompt_text, pte_task_type, reference_answer_text, rejection_reason, revision_group_public_id, revision_number, status, supersedes_public_id, task_type_key, task_type_section, tenant_id, title, version, visibility) VALUES ('c297777a-2b55-47f9-a42c-a58e7f625614','2026-10-28 16:07:24.357783+00','2026-10-28 16:07:24.369138+00',false,'f04eab73-566e-4f02-a8a4-4bea48034fa6',(SELECT public_id FROM public.users WHERE username = 'admin@local.com'),'t','t','f',NULL,'t','t',NULL,NULL,NULL,'EXAM','You manage a small local library and have arranged a space within it for community members to study and work. Upon a routine check, you find that the area is cluttered with personal items left behind. You need to address this issue with the community members. What would you say to the community members?','RESPOND_TO_A_SITUATION','I wanted to talk about the condition of our shared study space in the library. This area is a valuable resource for our community. To maintain its usefulness and ensure it remains welcoming for everyone, I kindly ask that you please clean up after yourselves, respect the furniture, and keep the space tidy. Your cooperation is greatly appreciated in keeping our library a conducive place for learning and collaboration. Thank you for your understanding and help.',NULL,'7820088f-c8bd-4329-b394-29e339650951','1','APPROVED',NULL,'RESPOND_TO_A_SITUATION','SPEAKING',NULL,'DOC22 RESPOND_TO_A_SITUATION 6eeb20bcd0636e18 | Shared Study Space','1','SHARED') ON CONFLICT (public_id) DO NOTHING;
INSERT INTO public.questions (public_id, created_at, updated_at, deleted, audio_prompt_ref, author_user_public_id, availability_flags_explicit, available_for_exam, available_for_practice, correct_answer_text, is_current, ever_published, image_prompt_ref, max_word_count, min_word_count, pool, prompt_text, pte_task_type, reference_answer_text, rejection_reason, revision_group_public_id, revision_number, status, supersedes_public_id, task_type_key, task_type_section, tenant_id, title, version, visibility) VALUES ('408ed319-0f58-42cf-8444-913e684d185b','2026-10-28 16:07:25.568578+00','2026-10-28 16:07:25.5786+00',false,'79df8377-11d0-43ff-b205-368db17f25e2',(SELECT public_id FROM public.users WHERE username = 'admin@local.com'),'t','t','f',NULL,'t','t',NULL,NULL,NULL,'EXAM','During a team meeting on Tuesday, your supervisor asks if you can complete and submit a comprehensive project update for a client by Friday. However, you''re waiting on essential feedback from a key team member who''s out of the office until Thursday. What would you say to your supervisor?','RESPOND_TO_A_SITUATION','Actually, I might need a bit more time to get that project update ready for the client. The thing is, I''m waiting on some important feedback from one of our team members who''s out until Thursday. It''s really cutting it close for me to compile everything and make sure it''s all good by Friday. I was hoping we could maybe push the deadline to Monday? This way, I can make sure everything''s on point. Really appreciate your understanding on this!',NULL,'e5694e5e-8444-4ce2-9bc2-d05f3d78bf04','1','APPROVED',NULL,'RESPOND_TO_A_SITUATION','SPEAKING',NULL,'DOC22 RESPOND_TO_A_SITUATION 875352ef33ff064d | Deadline Extension','1','SHARED') ON CONFLICT (public_id) DO NOTHING;
INSERT INTO public.questions (public_id, created_at, updated_at, deleted, audio_prompt_ref, author_user_public_id, availability_flags_explicit, available_for_exam, available_for_practice, correct_answer_text, is_current, ever_published, image_prompt_ref, max_word_count, min_word_count, pool, prompt_text, pte_task_type, reference_answer_text, rejection_reason, revision_group_public_id, revision_number, status, supersedes_public_id, task_type_key, task_type_section, tenant_id, title, version, visibility) VALUES ('4c51bd3a-81ff-4b2f-8321-a9f91ccfeda5','2026-10-28 16:07:26.57321+00','2026-10-28 16:07:26.584735+00',false,'a9ee82f7-32c4-4a93-bea2-28ff03463426',(SELECT public_id FROM public.users WHERE username = 'admin@local.com'),'t','t','f',NULL,'t','t',NULL,NULL,NULL,'EXAM','You book a spa day based on glowing reviews and a wide range of services listed online. When you arrive, half the services are unavailable, and the facilities are not as advertised. How do you address this with the spa manager?','RESPOND_TO_A_SITUATION','It was quite a letdown to see many services aren''t available and the facilities aren''t as great as I expected. I was looking forward to the full experience. To make up for this gap between what was advertised and what''s provided, could we maybe work out a partial refund or perhaps a voucher for a future visit when all services are back? I think that''d be a fair way to ensure I still get the relaxing experience I was excited about.',NULL,'a86927f3-68b3-4081-b9f6-4f2cd55d3b4e','1','APPROVED',NULL,'RESPOND_TO_A_SITUATION','SPEAKING',NULL,'DOC22 RESPOND_TO_A_SITUATION 335eaffa8a33f9ab | A Spa Day','1','SHARED') ON CONFLICT (public_id) DO NOTHING;
INSERT INTO public.questions (public_id, created_at, updated_at, deleted, audio_prompt_ref, author_user_public_id, availability_flags_explicit, available_for_exam, available_for_practice, correct_answer_text, is_current, ever_published, image_prompt_ref, max_word_count, min_word_count, pool, prompt_text, pte_task_type, reference_answer_text, rejection_reason, revision_group_public_id, revision_number, status, supersedes_public_id, task_type_key, task_type_section, tenant_id, title, version, visibility) VALUES ('694a456d-db80-4a88-bc6b-9f6f94e9fee9','2026-10-28 16:07:26.601369+00','2026-10-28 16:07:26.611428+00',false,NULL,(SELECT public_id FROM public.users WHERE username = 'admin@local.com'),'t','t','f',NULL,'t','t',NULL,'75','5','EXAM','11 February 2009 – Major athletic events around the globe – from the 2014 Sochi Olympics to an annual powerboat race in Norwegian fjords – are striving to neutralize their carbon footprint as part of a world-wide climate network, the United Nations Environment Programme (UNEP) said today.
INSERT INTO public.questions (public_id, created_at, updated_at, deleted, audio_prompt_ref, author_user_public_id, availability_flags_explicit, available_for_exam, available_for_practice, correct_answer_text, is_current, ever_published, image_prompt_ref, max_word_count, min_word_count, pool, prompt_text, pte_task_type, reference_answer_text, rejection_reason, revision_group_public_id, revision_number, status, supersedes_public_id, task_type_key, task_type_section, tenant_id, title, version, visibility) VALUES ('fe7c10f6-3b87-4ff7-8e50-b2a17b0cb630','2026-10-28 16:07:26.62448+00','2026-10-28 16:07:26.636437+00',false,NULL,(SELECT public_id FROM public.users WHERE username = 'admin@local.com'),'t','t','f',NULL,'t','t',NULL,'75','5','EXAM','Madeline Gannon is a researcher, teacher at the Carnegie Mellon University School of Architecture and Ph.D. candidate in Computational Design — but that’s not all. She is on a mission to open up the infinite design possibilities of 3D printing to the world. “Currently you have to have a lot of technical background in order to participate in creating things for 3D printers,” Gannon says. “There is still a huge knowledge barrier for how we create digital models.” As the technology has advanced, prices have plummeted, and now anyone can buy a 3D printer for a few hundred dollars, Gannon notes. However, not just anyone can create original designs for 3D-printed artifacts. To put true creative power into the hands of any ordinary 3D printer owner, Gannon has developed an innovative new system called ''Tactum''. Tactum is a new type of software that lets users create their own unique designs for 3D printers by simply touching a projected image. Using their innate hand gestures, someone using Tactum can poke, rub and otherwise manipulate the projected image that will become their 3D printed object, and see it instantly change shape in response. In keeping with the goal of democratizing the process, Gannon designed her first series of Tactum artifacts on a surface that everyone can access freely and manipulate instinctively, that being the human body.
INSERT INTO public.questions (public_id, created_at, updated_at, deleted, audio_prompt_ref, author_user_public_id, availability_flags_explicit, available_for_exam, available_for_practice, correct_answer_text, is_current, ever_published, image_prompt_ref, max_word_count, min_word_count, pool, prompt_text, pte_task_type, reference_answer_text, rejection_reason, revision_group_public_id, revision_number, status, supersedes_public_id, task_type_key, task_type_section, tenant_id, title, version, visibility) VALUES ('61647b8d-9f99-4f7a-be1e-36cfae572389','2026-10-28 16:07:26.653055+00','2026-10-28 16:07:26.663874+00',false,NULL,(SELECT public_id FROM public.users WHERE username = 'admin@local.com'),'t','t','f',NULL,'t','t',NULL,'300','200','EXAM','“The only thing that interferes with my learning is education.” – Albert Einstein. What did he mean by that? Do you think he is correct?','WRITE_ESSAY',NULL,NULL,'0f40363b-415e-4fbe-9d50-d5b31bf003e2','1','APPROVED',NULL,'WRITE_ESSAY','WRITING',NULL,'DOC22 WRITE_ESSAY 43cef331df3475b9 | Einstein','1','SHARED') ON CONFLICT (public_id) DO NOTHING;
INSERT INTO public.questions (public_id, created_at, updated_at, deleted, audio_prompt_ref, author_user_public_id, availability_flags_explicit, available_for_exam, available_for_practice, correct_answer_text, is_current, ever_published, image_prompt_ref, max_word_count, min_word_count, pool, prompt_text, pte_task_type, reference_answer_text, rejection_reason, revision_group_public_id, revision_number, status, supersedes_public_id, task_type_key, task_type_section, tenant_id, title, version, visibility) VALUES ('962a4329-d706-4259-a6c3-4ecac00b4116','2026-10-28 16:07:26.709795+00','2026-10-28 16:07:26.724918+00',false,NULL,(SELECT public_id FROM public.users WHERE username = 'admin@local.com'),'t','t','f','1.received, 2.played, 3.which, 4.In addition to','t','t',NULL,NULL,NULL,'EXAM','Victoria University of Wellington has conferred an honorary degree on a distinguished astrophysicist in a recent graduation ceremony. Professor Warrick Couch {{0}} the honorary degree of Doctor of Science for his remarkable contribution to our knowledge of galaxies and dark energy. Professor Couch is a distinguished astrophysicist who has {{1}} a crucial role in the discovery that the Universe is expanding at an accelerating rate, a finding which led to the lead scientists being awarded a Nobel Prize in Physics in 2011, which he attended in recognition of his contribution.
INSERT INTO public.questions (public_id, created_at, updated_at, deleted, audio_prompt_ref, author_user_public_id, availability_flags_explicit, available_for_exam, available_for_practice, correct_answer_text, is_current, ever_published, image_prompt_ref, max_word_count, min_word_count, pool, prompt_text, pte_task_type, reference_answer_text, rejection_reason, revision_group_public_id, revision_number, status, supersedes_public_id, task_type_key, task_type_section, tenant_id, title, version, visibility) VALUES ('3b042f0d-577f-4881-ae08-6bc3a34b5971','2026-10-28 16:07:26.735927+00','2026-10-28 16:07:26.748654+00',false,NULL,(SELECT public_id FROM public.users WHERE username = 'admin@local.com'),'t','t','f','1.drawn, 2.prolific, 3.at least, 4.whom','t','t',NULL,NULL,NULL,'EXAM','Keith Haring began as an underground artist, literally. His first famous projects were pieces of stylized graffiti {{1}} in New York subway stations. Haring travelled from station to station, drawing with chalk and chatting with commuters about his work. These doodles helped him develop his classic style and he grew so {{2}} , doing up to 40 drawings a day, that it was not long before fame and a measure of fortune followed.
INSERT INTO public.questions (public_id, created_at, updated_at, deleted, audio_prompt_ref, author_user_public_id, availability_flags_explicit, available_for_exam, available_for_practice, correct_answer_text, is_current, ever_published, image_prompt_ref, max_word_count, min_word_count, pool, prompt_text, pte_task_type, reference_answer_text, rejection_reason, revision_group_public_id, revision_number, status, supersedes_public_id, task_type_key, task_type_section, tenant_id, title, version, visibility) VALUES ('a0741492-2bb3-44f7-9105-1aa8c55ccce1','2026-10-28 16:07:26.762857+00','2026-10-28 16:07:26.77595+00',false,NULL,(SELECT public_id FROM public.users WHERE username = 'admin@local.com'),'t','t','f','1.does, 2.across, 3.Instead, 4.followed, 5.rule','t','t',NULL,NULL,NULL,'EXAM','Comparing the intelligence of animals of different species is difficult, how do you compare a dolphin and a horse? Psychologists have a technique for looking at intelligence that {{1}} not require the cooperation of the animal involved. The relative size of an individual''s brain is a reasonable indication of intelligence. Comparing {{2}} species is not as simple as generally expected. An elephant will have a larger brain than a human has simply because it is a large beast. {{3}} , we use the Cephalization index, which compares the size of an animal''s brain with the size of its body. Based on the Cephalization index, the brightest animals on the planet are humans, {{4}} by great apes, porpoises and elephants. As a general {{5}} , animals that hunt for a living (like canines) are smarter than strict vegetarians (you don''t need much intelligence to outsmart a leaf of lettuce). Animals that live in social groups are always smarter and have larger EQ''s than solitary animals.','FILL_IN_THE_BLANKS_DROPDOWN',NULL,NULL,'f1e3422a-8132-4559-a5dc-6ec491032f1f','1','APPROVED',NULL,'FILL_IN_THE_BLANKS_DROPDOWN','READING',NULL,'DOC22 FILL_IN_THE_BLANKS_DROPDOWN a26b6b029a5d1799 | Intelligence Comparison','1','SHARED') ON CONFLICT (public_id) DO NOTHING;
INSERT INTO public.questions (public_id, created_at, updated_at, deleted, audio_prompt_ref, author_user_public_id, availability_flags_explicit, available_for_exam, available_for_practice, correct_answer_text, is_current, ever_published, image_prompt_ref, max_word_count, min_word_count, pool, prompt_text, pte_task_type, reference_answer_text, rejection_reason, revision_group_public_id, revision_number, status, supersedes_public_id, task_type_key, task_type_section, tenant_id, title, version, visibility) VALUES ('00c0c108-0b28-4d8b-baec-ebb2311b75c3','2026-10-28 16:07:26.789384+00','2026-10-28 16:07:26.803834+00',false,NULL,(SELECT public_id FROM public.users WHERE username = 'admin@local.com'),'t','t','f','1.precise, 2.involved, 3.rather than, 4.Similarly, 5.bonus','t','t',NULL,NULL,NULL,'EXAM','People are living longer and this longevity is good news for sales teams. It results in a much more {{1}} customer base for them to work from. Why we are living longer is not the issue for anyone {{2}} in drawing up plans to market a product. What they focus on is the fact that there are now more age groups to target, which means that a sales pitch can be re-worked a number of times to more exactly fit each one. For example, {{3}} referring simply to ''adults'', there are now ''starting adults'', ''young adults'' and ''established adults''. {{4}} , markets no longer talk about ''children'', but tend to refer to a fuller range of categories that includes ''kids'', ''tweens'', ''pre-teens'' and ''teenagers''. We now have a very diverse population in terms of age, and that can only be a {{5}} for business.','FILL_IN_THE_BLANKS_DROPDOWN',NULL,NULL,'4a38d426-9171-4ab6-ac25-33f5111027ba','1','APPROVED',NULL,'FILL_IN_THE_BLANKS_DROPDOWN','READING',NULL,'DOC22 FILL_IN_THE_BLANKS_DROPDOWN f803ff4baa97369e | Longevity','1','SHARED') ON CONFLICT (public_id) DO NOTHING;
INSERT INTO public.questions (public_id, created_at, updated_at, deleted, audio_prompt_ref, author_user_public_id, availability_flags_explicit, available_for_exam, available_for_practice, correct_answer_text, is_current, ever_published, image_prompt_ref, max_word_count, min_word_count, pool, prompt_text, pte_task_type, reference_answer_text, rejection_reason, revision_group_public_id, revision_number, status, supersedes_public_id, task_type_key, task_type_section, tenant_id, title, version, visibility) VALUES ('cd3454ce-7b30-485f-8e77-56f1dd7785ba','2026-10-28 16:07:26.81747+00','2026-10-28 16:07:26.834517+00',false,NULL,(SELECT public_id FROM public.users WHERE username = 'admin@local.com'),'t','t','f','1.motivation, 2.factors, 3.include, 4.congestion, 5.interact','t','t',NULL,NULL,NULL,'EXAM','People move to a new region for many different reasons. The {{1}} for moving can come from a combination of what researchers sometimes call ''push and pull {{2}} '' — those that encourage people to leave a region, and those that attract people to a region. Some of the factors that motivate people to move {{3}} seeking a better climate, finding more affordable housing, looking for work or retiring from work, leaving the {{4}} of city living, wanting a more pleasant environment, and wanting to be near to family and friends. In reality, many complex factors and personal reasons may {{5}} to motivate a person or family to move.','FILL_IN_THE_BLANKS_DROPDOWN',NULL,NULL,'67b66b32-5c90-4323-80b8-10952e47bf70','1','APPROVED',NULL,'FILL_IN_THE_BLANKS_DROPDOWN','READING',NULL,'DOC22 FILL_IN_THE_BLANKS_DROPDOWN af800fc575682ca1 | Push and Pull','1','SHARED') ON CONFLICT (public_id) DO NOTHING;
INSERT INTO public.questions (public_id, created_at, updated_at, deleted, audio_prompt_ref, author_user_public_id, availability_flags_explicit, available_for_exam, available_for_practice, correct_answer_text, is_current, ever_published, image_prompt_ref, max_word_count, min_word_count, pool, prompt_text, pte_task_type, reference_answer_text, rejection_reason, revision_group_public_id, revision_number, status, supersedes_public_id, task_type_key, task_type_section, tenant_id, title, version, visibility) VALUES ('3998fd72-ecdb-4af3-96e4-24c8799226fc','2026-10-28 16:07:26.847192+00','2026-10-28 16:07:26.863415+00',false,NULL,(SELECT public_id FROM public.users WHERE username = 'admin@local.com'),'t','t','f','1.of becoming, 2.prefer, 3.has had, 4.deal, 5.argue','t','t',NULL,NULL,NULL,'EXAM','At the moment, there are between six and seven thousand languages in the world. According to linguists, fifty percent of these are in danger {{1}} extinct. The speed of language loss has accelerated over the past few decades because businesses that need to communicate with a range of people from other cultures {{2}} to employ more widely used languages, such as English, Chinese, or Spanish. This attitude is understandable, but it means that many local languages are dying out before anyone {{3}} the opportunity to study them. According to linguists, some of these languages could reveal a great {{4}} of useful information about language learning and cognitive development. In addition, a local language that has been built on the local culture contains words and phrases that express that culture; lose the language and you arguably may lose the culture, too. And finally, historians will {{5}} that a language contains evidence of a region''s history and should, for that reason alone, be preserved.','FILL_IN_THE_BLANKS_DROPDOWN',NULL,NULL,'c84e32c5-d672-4565-a3f1-5b181f57dc31','1','APPROVED',NULL,'FILL_IN_THE_BLANKS_DROPDOWN','READING',NULL,'DOC22 FILL_IN_THE_BLANKS_DROPDOWN c60abdb5cef3a8e7 | Language Extinct','1','SHARED') ON CONFLICT (public_id) DO NOTHING;
INSERT INTO public.questions (public_id, created_at, updated_at, deleted, audio_prompt_ref, author_user_public_id, availability_flags_explicit, available_for_exam, available_for_practice, correct_answer_text, is_current, ever_published, image_prompt_ref, max_word_count, min_word_count, pool, prompt_text, pte_task_type, reference_answer_text, rejection_reason, revision_group_public_id, revision_number, status, supersedes_public_id, task_type_key, task_type_section, tenant_id, title, version, visibility) VALUES ('e278486a-39b5-4bc2-8148-2a9c26c675f0','2026-10-28 16:07:26.877934+00','2026-10-28 16:07:26.892861+00',false,NULL,(SELECT public_id FROM public.users WHERE username = 'admin@local.com'),'t','t','f','the nature of the climate there
INSERT INTO public.questions (public_id, created_at, updated_at, deleted, audio_prompt_ref, author_user_public_id, availability_flags_explicit, available_for_exam, available_for_practice, correct_answer_text, is_current, ever_published, image_prompt_ref, max_word_count, min_word_count, pool, prompt_text, pte_task_type, reference_answer_text, rejection_reason, revision_group_public_id, revision_number, status, supersedes_public_id, task_type_key, task_type_section, tenant_id, title, version, visibility) VALUES ('45229951-8e59-4417-bb96-640d20d1a1dd','2026-10-28 16:07:37.894502+00','2026-10-28 16:07:37.904804+00',false,'3b9f5acc-4fdc-446e-a66d-4e57cc54b95c',(SELECT public_id FROM public.users WHERE username = 'admin@local.com'),'t','t','f','What we experience is processed by the brain into memories in three stages. First, there is the sensory input, which is momentary. This is then stored in the short-term memory. If this experience is important or meaningful to us, we will reinforce the memory, possibly by repetition, and it will then be stored in the long-term memory.','t','t',NULL,NULL,NULL,'EXAM','In his great novel Remembrance of Things Past or In Search of Lost Time, Marcel Proust explored what are called "involuntary memories" - those that come to us quite suddenly without conscious effort, usually triggered by one of the senses. The fact that his book has two titles in English might suggest there is some doubt as to how our minds go about remembering things. In perhaps the most well-known such episode in the novel, the character Marcel is reminded of his childhood by the aroma produced when dunking a cake in a cup of tea. This is not far away from the belief that as we get older we can remember quite clearly incidents from years ago, but find it hard to remember what we did last week. Proust''s insight into memory is certainly true of one way the mind works. But why and how do we remember what we do?
INSERT INTO public.questions (public_id, created_at, updated_at, deleted, audio_prompt_ref, author_user_public_id, availability_flags_explicit, available_for_exam, available_for_practice, correct_answer_text, is_current, ever_published, image_prompt_ref, max_word_count, min_word_count, pool, prompt_text, pte_task_type, reference_answer_text, rejection_reason, revision_group_public_id, revision_number, status, supersedes_public_id, task_type_key, task_type_section, tenant_id, title, version, visibility) VALUES ('8b911c38-dd0a-4843-90aa-8f8107d8a792','2026-10-28 16:07:27.144541+00','2026-10-28 16:07:27.15543+00',false,NULL,(SELECT public_id FROM public.users WHERE username = 'admin@local.com'),'t','t','f','1.recruits, 2.remained, 3.aspect, 4.limit, 5.varied','t','t',NULL,NULL,NULL,'EXAM','Thea Proctor was just sixteen when her entry at the Bowral Art Competition caught the eye of the judge, Arthur Streeton. It was the first of many associations with art world {{1}} . The next year saw her at the Julian Ashton Art School in the illustrious company of Elioth Gruner, Sydney Long and George Lambert, for whom she often posed and who {{2}} her great friend until his death in 1930. Lambert''s paintings and sketches of Proctor emphasize the elegance of her dress. A keen interest in fashion was just one {{3}} of her fascination with design, and she saw herself as an early style guru on a quest to rid Australian art of "its lack of imagination and inventive design". Skilled in watercolor and drawing, Proctor did not {{4}} herself to paper, canvases or to her popular magazine illustrations; she designed theater sets and a restaurant interior and wrote on a range of subjects from flower arranging to the colors of cars. It made for a busy and {{5}} life but, as she said, she was not the sort of person "who could sit at home and knit socks."','FILL_IN_THE_BLANKS_DRAG_AND_DROP',NULL,NULL,'6f126347-1837-4f8c-95a0-2caf87f91061','1','APPROVED',NULL,'FILL_IN_THE_BLANKS_DRAG_AND_DROP','READING',NULL,'DOC22 FILL_IN_THE_BLANKS_DRAG_AND_DROP 375ea9613fcb34f0 | Thea Proctor','1','SHARED') ON CONFLICT (public_id) DO NOTHING;
