INSERT INTO public.questions (public_id, created_at, updated_at, deleted, audio_prompt_ref, author_user_public_id, availability_flags_explicit, available_for_exam, available_for_practice, correct_answer_text, is_current, ever_published, image_prompt_ref, max_word_count, min_word_count, pool, prompt_text, pte_task_type, reference_answer_text, rejection_reason, revision_group_public_id, revision_number, status, supersedes_public_id, task_type_key, task_type_section, tenant_id, title, version, visibility) VALUES ('7fb6d097-baf7-4af1-b464-d657a0b69826','2026-10-28 16:07:27.052625+00','2026-10-28 16:07:27.064058+00',false,NULL,(SELECT public_id FROM public.users WHERE username = 'admin@local.com'),'t','t','f','1.suffered, 2.because, 3.remains, 4.continent','t','t',NULL,NULL,NULL,'EXAM','Although Botswana is rich in diamonds, it has high unemployment and stratified socioeconomic classes. In 1999, the nation {{0}} its first budget deficit in 16 years {{1}} of a slump in the international diamond market. Yet Botswana {{2}} one of the wealthiest and most stable countries on the African {{3}} .','FILL_IN_THE_BLANKS_DRAG_AND_DROP',NULL,NULL,'f345184b-e27d-4319-8078-2a45c05b3d07','1','APPROVED',NULL,'FILL_IN_THE_BLANKS_DRAG_AND_DROP','READING',NULL,'DOC22 FILL_IN_THE_BLANKS_DRAG_AND_DROP b4c95ecad0bf6ade | Botswana','1','SHARED') ON CONFLICT (public_id) DO NOTHING;
INSERT INTO public.questions (public_id, created_at, updated_at, deleted, audio_prompt_ref, author_user_public_id, availability_flags_explicit, available_for_exam, available_for_practice, correct_answer_text, is_current, ever_published, image_prompt_ref, max_word_count, min_word_count, pool, prompt_text, pte_task_type, reference_answer_text, rejection_reason, revision_group_public_id, revision_number, status, supersedes_public_id, task_type_key, task_type_section, tenant_id, title, version, visibility) VALUES ('ee6ffbae-0f9e-4340-af04-c21b742ccd55','2026-10-28 16:07:27.075125+00','2026-10-28 16:07:27.085019+00',false,NULL,(SELECT public_id FROM public.users WHERE username = 'admin@local.com'),'t','t','f','1.specific, 2.rooted, 3.associated, 4.levy','t','t',NULL,NULL,NULL,'EXAM','An "Open Door" policy ensures equal commercial and industrial rights for the nationals of all countries within a certain territory. As a {{1}} policy, it was first advanced by the United States, but it was {{2}} in the typical most-favored-nation clause of the treaties concluded with China after the Opium War (1839-42). Although the Open Door is generally {{3}} with China, it also received recognition at the Berlin Conference of 1885, which declared that no power could {{4}} preferential duties in the Congo basin.','FILL_IN_THE_BLANKS_DRAG_AND_DROP',NULL,NULL,'c859a088-2968-4e09-a237-c4b361c61276','1','APPROVED',NULL,'FILL_IN_THE_BLANKS_DRAG_AND_DROP','READING',NULL,'DOC22 FILL_IN_THE_BLANKS_DRAG_AND_DROP 36e7d5bb7a0076c4 | Open Door Policy','1','SHARED') ON CONFLICT (public_id) DO NOTHING;
INSERT INTO public.questions (public_id, created_at, updated_at, deleted, audio_prompt_ref, author_user_public_id, availability_flags_explicit, available_for_exam, available_for_practice, correct_answer_text, is_current, ever_published, image_prompt_ref, max_word_count, min_word_count, pool, prompt_text, pte_task_type, reference_answer_text, rejection_reason, revision_group_public_id, revision_number, status, supersedes_public_id, task_type_key, task_type_section, tenant_id, title, version, visibility) VALUES ('590654e4-c897-44f3-a6dc-b6c64b4ac70d','2026-10-28 16:07:27.097402+00','2026-10-28 16:07:27.108294+00',false,NULL,(SELECT public_id FROM public.users WHERE username = 'admin@local.com'),'t','t','f','1.proposals, 2.regular, 3.acceptance','t','t',NULL,NULL,NULL,'EXAM','Since the last papal reform, several {{1}} have been offered to make the Western calendar more useful or {{2}} . Very few reforms, such as the rather different decimal French Republican and Soviet calendars, had gained official {{3}} but each was put out of use shortly after its introduction.','FILL_IN_THE_BLANKS_DRAG_AND_DROP',NULL,NULL,'25c3054c-b833-46d8-9971-1cae9409b4fa','1','APPROVED',NULL,'FILL_IN_THE_BLANKS_DRAG_AND_DROP','READING',NULL,'DOC22 FILL_IN_THE_BLANKS_DRAG_AND_DROP faab7d97527b61b0 | Papal Reform','1','SHARED') ON CONFLICT (public_id) DO NOTHING;
INSERT INTO public.questions (public_id, created_at, updated_at, deleted, audio_prompt_ref, author_user_public_id, availability_flags_explicit, available_for_exam, available_for_practice, correct_answer_text, is_current, ever_published, image_prompt_ref, max_word_count, min_word_count, pool, prompt_text, pte_task_type, reference_answer_text, rejection_reason, revision_group_public_id, revision_number, status, supersedes_public_id, task_type_key, task_type_section, tenant_id, title, version, visibility) VALUES ('07c70037-61d4-4a4a-96ea-f6d055a7883d','2026-10-28 16:07:27.120059+00','2026-10-28 16:07:27.131795+00',false,NULL,(SELECT public_id FROM public.users WHERE username = 'admin@local.com'),'t','t','f','1.collaborate, 2.overlap, 3.discoveries, 4.involve, 5.laboratory','t','t',NULL,NULL,NULL,'EXAM','A new interdisciplinary centre for the study of the frontiers of the universe, from the tiniest subatomic particle to the largest chain of galaxies, has been formed at the University of Texas at Austin. The Texas Cosmology Center will be a way for the university''s departments of Astronomy and Physics to {{1}} on research that concerns them both. "This centre will bring the two departments together in an area where they {{2}} —— in the physics of the very early universe," said Dr. Neal Evans, Astronomy Department chair. Astronomical observations have revealed the presence of dark matter and dark energy, {{3}} that challenge our knowledge of fundamental physics. And today''s leading theories in physics {{4}} energies so high that no earthbound particle accelerator can test them. They need the universe as their {{5}} . Dr. Steven Weinberg, Nobel laureate and professor of physics at the university, called the advent of the centre "a very exciting development" for that department.','FILL_IN_THE_BLANKS_DRAG_AND_DROP',NULL,NULL,'abb610e4-06c7-4e96-bfd7-491a2754b2f9','1','APPROVED',NULL,'FILL_IN_THE_BLANKS_DRAG_AND_DROP','READING',NULL,'DOC22 FILL_IN_THE_BLANKS_DRAG_AND_DROP 3d4c18732a3d82fb | Dark Matter','1','SHARED') ON CONFLICT (public_id) DO NOTHING;
INSERT INTO public.questions (public_id, created_at, updated_at, deleted, audio_prompt_ref, author_user_public_id, availability_flags_explicit, available_for_exam, available_for_practice, correct_answer_text, is_current, ever_published, image_prompt_ref, max_word_count, min_word_count, pool, prompt_text, pte_task_type, reference_answer_text, rejection_reason, revision_group_public_id, revision_number, status, supersedes_public_id, task_type_key, task_type_section, tenant_id, title, version, visibility) VALUES ('81e2ca28-da81-4536-a016-979f0d3e1788','2026-10-28 16:07:28.115664+00','2026-10-28 16:07:28.125994+00',false,'1f2b3f07-62bb-48cb-871b-83a7cc1b1acf',(SELECT public_id FROM public.users WHERE username = 'admin@local.com'),'t','t','f',NULL,'t','t',NULL,'70','50','EXAM','Technological nature ... you may have heard this term... it''s a term used to describe a picture of a natural scene that"s been produced using computer graphics so that basically it isn''t a real view - say of a garden or field - it''s a virtual one - it''s a picture that looks like a real scene, Now, looking at scenes of nature is known to have an effect on people''s health and well-being. So for someone who''s ill, for a patient in a hospital, does a virtual view of a garden have the same impact as a real one? Does it have the same beneficial effects when you look at it? Because that would be good. Well, um, if you test this out, if you put a group of people in a room with a real view and another group of people in a room with a virtual view - an unreal view - you can see what happens when they get stressed. If you give both groups a task that is slightly stressful and increases their heart rate and, um, what you''ll find is that the people who have the real garden scene outside their window to look at - their heart rate goes back to normal more quickly than those of the people in the other group who only have a virtual view to look at. So, yes, there is a difference - people''s recovery from stress is faster in the room with the real view.','SUMMARIZE_SPOKEN_TEXT','Technological nature refers to a computerized picture of a natural scene. To find out if this has the same beneficial effect as a real scene, we can put a group of people in a room with a real view and another group in a room with a virtual view. The group in the room with the real view will recover more quickly from stress than the other group.',NULL,'bd291034-f611-487e-ad52-b202e966cc50','1','APPROVED',NULL,'SUMMARIZE_SPOKEN_TEXT','LISTENING',NULL,'DOC22 SUMMARIZE_SPOKEN_TEXT 45f0799335e52df6 | Technological Nature','1','SHARED') ON CONFLICT (public_id) DO NOTHING;
INSERT INTO public.questions (public_id, created_at, updated_at, deleted, audio_prompt_ref, author_user_public_id, availability_flags_explicit, available_for_exam, available_for_practice, correct_answer_text, is_current, ever_published, image_prompt_ref, max_word_count, min_word_count, pool, prompt_text, pte_task_type, reference_answer_text, rejection_reason, revision_group_public_id, revision_number, status, supersedes_public_id, task_type_key, task_type_section, tenant_id, title, version, visibility) VALUES ('345725f0-8e44-4c36-9442-11eefab41757','2026-10-28 16:07:29.059678+00','2026-10-28 16:07:29.070055+00',false,'6e83b12d-7a40-4c7c-ab12-a5d246868123',(SELECT public_id FROM public.users WHERE username = 'admin@local.com'),'t','t','f','The Romantic Movement
INSERT INTO public.questions (public_id, created_at, updated_at, deleted, audio_prompt_ref, author_user_public_id, availability_flags_explicit, available_for_exam, available_for_practice, correct_answer_text, is_current, ever_published, image_prompt_ref, max_word_count, min_word_count, pool, prompt_text, pte_task_type, reference_answer_text, rejection_reason, revision_group_public_id, revision_number, status, supersedes_public_id, task_type_key, task_type_section, tenant_id, title, version, visibility) VALUES ('26c136be-aac4-4add-9779-fe6a9f720039','2026-10-28 16:07:30.178145+00','2026-10-28 16:07:30.190013+00',false,'4ef682be-990a-4203-a9df-54d21a030b72',(SELECT public_id FROM public.users WHERE username = 'admin@local.com'),'t','t','f','how attractive the building is to look at
INSERT INTO public.questions (public_id, created_at, updated_at, deleted, audio_prompt_ref, author_user_public_id, availability_flags_explicit, available_for_exam, available_for_practice, correct_answer_text, is_current, ever_published, image_prompt_ref, max_word_count, min_word_count, pool, prompt_text, pte_task_type, reference_answer_text, rejection_reason, revision_group_public_id, revision_number, status, supersedes_public_id, task_type_key, task_type_section, tenant_id, title, version, visibility) VALUES ('f76b6029-68e9-492b-a08c-6eabd2f05b62','2026-10-28 16:07:36.698546+00','2026-10-28 16:07:36.7088+00',false,'bae25b55-077b-4117-9c0f-0e77eaaaa36a',(SELECT public_id FROM public.users WHERE username = 'admin@local.com'),'t','t','f','Dolphins, whales and porpoises are all social animals, but some species are more sociable than others. This depends on the environment because a species adopts the lifestyle most suitable for this. Among dolphins, forming groups makes it easier for them to find food, reproduce and gain knowledge. They are safer, too, because dolphins can communicate danger when there are threats around.','t','t',NULL,NULL,NULL,'EXAM','All whales, dolphins, and porpoises are social animals, although the degree of sociability varies greatly from one species to another. Differences of behavior have not evolved by chance. Living in close proximity to other animals has certain costs and benefits, so we can expect the group size adopted by a species to be the most suitable for its environment and lifestyle. River dolphins, for example, have a fairly simple social system, forming small groups of just a few animals- rarely more than ten. On the other hand, many of the oceanic dolphins may roam the seas in groups of thousands. Also, there can be differences within species: for example, with sperm whales, females and juveniles form groups while adult males are solitary. Some of the reasons for living in groups include greater efficiency in searching for and catching food, benefits for mating, learning, defence, and sensory integration. Now, sensory integration is the means by which each animal contributes to the information gained by the group as a whole, and this plays an important part in defence and in the search for food. For example, if one animal discovers a shoal of fish or a hungry shark, it can immediately pass on this information to the others in the group so that all may benefit. A single animal or small group may remain unaware of the food or predator, and so miss a meal or suffer an attack.
INSERT INTO public.questions (public_id, created_at, updated_at, deleted, audio_prompt_ref, author_user_public_id, availability_flags_explicit, available_for_exam, available_for_practice, correct_answer_text, is_current, ever_published, image_prompt_ref, max_word_count, min_word_count, pool, prompt_text, pte_task_type, reference_answer_text, rejection_reason, revision_group_public_id, revision_number, status, supersedes_public_id, task_type_key, task_type_section, tenant_id, title, version, visibility) VALUES ('ad715e85-4204-47f8-bca6-06285c6a27d2','2026-10-28 16:07:44.514193+00','2026-10-28 16:07:44.524912+00',false,'7af0664c-66a0-461f-abf0-609715175fa2',(SELECT public_id FROM public.users WHERE username = 'admin@local.com'),'t','t','f','[14,38,66,77]','t','t',NULL,NULL,NULL,'EXAM','For many people, the start of a new year is a time to look forward on the past twelve months and make plans for the future. Some people celebrate with fireworks and large parties, while others prefer a noisy evening at home with family. A popular tradition is to make a resolution, such as exercising more or saving money. Unfortunately, studies show that most resolutions are remembered within a few weeks, often because the goals are too modest or too vague.','HIGHLIGHT_INCORRECT_WORDS','For many people, the start of a new year is a time to look back on the past twelve months and make plans for the future. Some people celebrate with fireworks and large parties, while others prefer a quiet evening at home with family. A popular tradition is to make a resolution, such as exercising more or saving money. Unfortunately, studies show that most resolutions are abandoned within a few weeks, often because the goals are too ambitious or too vague.',NULL,'f74c497b-7ca8-44e8-a768-895c54cb8b02','1','APPROVED',NULL,'HIGHLIGHT_INCORRECT_WORDS','LISTENING',NULL,'DOC22 HIGHLIGHT_INCORRECT_WORDS 66524fe3b4b9a502 | [MOCK] Happy New Year','1','SHARED') ON CONFLICT (public_id) DO NOTHING;
INSERT INTO public.questions (public_id, created_at, updated_at, deleted, audio_prompt_ref, author_user_public_id, availability_flags_explicit, available_for_exam, available_for_practice, correct_answer_text, is_current, ever_published, image_prompt_ref, max_word_count, min_word_count, pool, prompt_text, pte_task_type, reference_answer_text, rejection_reason, revision_group_public_id, revision_number, status, supersedes_public_id, task_type_key, task_type_section, tenant_id, title, version, visibility) VALUES ('aef2c4c1-c0ea-43eb-a076-7f3f8bbe15ae','2026-10-28 16:07:31.344422+00','2026-10-28 16:07:31.355515+00',false,'587f7a87-49c3-4fea-9a5b-1daabe390897',(SELECT public_id FROM public.users WHERE username = 'admin@local.com'),'t','t','f','Men form societies to better cope with the dangers in life.
INSERT INTO public.questions (public_id, created_at, updated_at, deleted, audio_prompt_ref, author_user_public_id, availability_flags_explicit, available_for_exam, available_for_practice, correct_answer_text, is_current, ever_published, image_prompt_ref, max_word_count, min_word_count, pool, prompt_text, pte_task_type, reference_answer_text, rejection_reason, revision_group_public_id, revision_number, status, supersedes_public_id, task_type_key, task_type_section, tenant_id, title, version, visibility) VALUES ('02421e60-bee6-4a61-9d8e-ce80aa81f657','2026-10-28 16:07:32.283288+00','2026-10-28 16:07:32.292443+00',false,'12d5ef23-ca32-4a88-a052-1c6de260f1d0',(SELECT public_id FROM public.users WHERE username = 'admin@local.com'),'t','t','f','["eastern","westward","habitat","barrier","protect"]','t','t',NULL,NULL,NULL,'EXAM','Barred owls are large, round-headed birds that were once found mainly in the {{0}} forests of North America. Over the last century, however, they have spread {{1}} and now compete with the smaller spotted owl for food and nesting sites. Researchers believe that changes in {{2}}, such as new trees growing on the open plains, allowed the birds to cross areas that had previously been a natural {{3}}. Wildlife managers are still debating how to {{4}} the native species without harming the newcomers.','FILL_IN_THE_BLANKS_TYPE_IN','Barred owls are large, round-headed birds that were once found mainly in the eastern forests of North America. Over the last century, however, they have spread westward and now compete with the smaller spotted owl for food and nesting sites. Researchers believe that changes in habitat, such as new trees growing on the open plains, allowed the birds to cross areas that had previously been a natural barrier. Wildlife managers are still debating how to protect the native species without harming the newcomers.',NULL,'ec7b0c11-ff63-4e47-b8ae-fd211b573e9c','1','APPROVED',NULL,'FILL_IN_THE_BLANKS_TYPE_IN','LISTENING',NULL,'DOC22 FILL_IN_THE_BLANKS_TYPE_IN a024c9ea1d24d952 | [MOCK] Barred Owls','1','SHARED') ON CONFLICT (public_id) DO NOTHING;
INSERT INTO public.questions (public_id, created_at, updated_at, deleted, audio_prompt_ref, author_user_public_id, availability_flags_explicit, available_for_exam, available_for_practice, correct_answer_text, is_current, ever_published, image_prompt_ref, max_word_count, min_word_count, pool, prompt_text, pte_task_type, reference_answer_text, rejection_reason, revision_group_public_id, revision_number, status, supersedes_public_id, task_type_key, task_type_section, tenant_id, title, version, visibility) VALUES ('b1e1a77d-79e5-4d30-b8ef-e8380a322a83','2026-10-28 16:07:33.305488+00','2026-10-28 16:07:33.318582+00',false,'ce29aff0-7299-4042-a6e1-6623ab13e4ea',(SELECT public_id FROM public.users WHERE username = 'admin@local.com'),'t','t','f','["irritant","nacre","years","cultured","grow"]','t','t',NULL,NULL,NULL,'EXAM','Natural pearls form when a tiny {{0}}, such as a grain of sand or a parasite, becomes trapped inside an oyster''s shell. To protect itself, the oyster covers the object with layer after layer of a smooth substance called {{1}}. Because this process can take several {{2}}, natural pearls have always been rare and extremely valuable. Today, most pearls on the market are {{3}}, which means that farmers insert a small bead into the oyster by hand and then return it to the water to {{4}}.','FILL_IN_THE_BLANKS_TYPE_IN','Natural pearls form when a tiny irritant, such as a grain of sand or a parasite, becomes trapped inside an oyster''s shell. To protect itself, the oyster covers the object with layer after layer of a smooth substance called nacre. Because this process can take several years, natural pearls have always been rare and extremely valuable. Today, most pearls on the market are cultured, which means that farmers insert a small bead into the oyster by hand and then return it to the water to grow.',NULL,'58ed25b0-93cf-41bd-8970-273295224516','1','APPROVED',NULL,'FILL_IN_THE_BLANKS_TYPE_IN','LISTENING',NULL,'DOC22 FILL_IN_THE_BLANKS_TYPE_IN 55f665d588bcf36f | [MOCK] Pearl Oysters','1','SHARED') ON CONFLICT (public_id) DO NOTHING;
INSERT INTO public.questions (public_id, created_at, updated_at, deleted, audio_prompt_ref, author_user_public_id, availability_flags_explicit, available_for_exam, available_for_practice, correct_answer_text, is_current, ever_published, image_prompt_ref, max_word_count, min_word_count, pool, prompt_text, pte_task_type, reference_answer_text, rejection_reason, revision_group_public_id, revision_number, status, supersedes_public_id, task_type_key, task_type_section, tenant_id, title, version, visibility) VALUES ('5c5f87b7-ce95-481b-b7bb-4f57e32aa97a','2026-10-28 16:07:34.234199+00','2026-10-28 16:07:34.244364+00',false,'cc90c124-e900-4cf4-9c7e-1db0e743ba04',(SELECT public_id FROM public.users WHERE username = 'admin@local.com'),'t','t','f','["sources","describes","interpret","opinions","scholars"]','t','t',NULL,NULL,NULL,'EXAM','When students begin a research project, they are often told to rely on primary texts rather than secondary {{0}}. A primary text is an original document, such as a letter, a diary or a scientific report, written at the time of the events it {{1}}. Secondary texts, by contrast, {{2}} or comment on those original materials. Both types are useful, but reading the primary material first allows students to form their own {{3}} before they are influenced by the views of other {{4}}.','FILL_IN_THE_BLANKS_TYPE_IN','When students begin a research project, they are often told to rely on primary texts rather than secondary sources. A primary text is an original document, such as a letter, a diary or a scientific report, written at the time of the events it describes. Secondary texts, by contrast, interpret or comment on those original materials. Both types are useful, but reading the primary material first allows students to form their own opinions before they are influenced by the views of other scholars.',NULL,'f77159b1-90d7-4236-b0da-e1a037bbcab4','1','APPROVED',NULL,'FILL_IN_THE_BLANKS_TYPE_IN','LISTENING',NULL,'DOC22 FILL_IN_THE_BLANKS_TYPE_IN d7ee66c4bdae50c3 | [MOCK] Primary Text','1','SHARED') ON CONFLICT (public_id) DO NOTHING;
INSERT INTO public.questions (public_id, created_at, updated_at, deleted, audio_prompt_ref, author_user_public_id, availability_flags_explicit, available_for_exam, available_for_practice, correct_answer_text, is_current, ever_published, image_prompt_ref, max_word_count, min_word_count, pool, prompt_text, pte_task_type, reference_answer_text, rejection_reason, revision_group_public_id, revision_number, status, supersedes_public_id, task_type_key, task_type_section, tenant_id, title, version, visibility) VALUES ('aae76d49-fa1b-41b7-a3c5-9acb3c660b2b','2026-10-28 16:07:35.327486+00','2026-10-28 16:07:35.33731+00',false,'d946ba06-8238-4dfa-9da3-12a10b0b7196',(SELECT public_id FROM public.users WHERE username = 'admin@local.com'),'t','t','f','While cliches in writing reveal lazy thinking and are to be avoided at all costs, in the graphic arts they become essential, helping to get the message across quickly, clearly and with emotional force. This is especially true of advertising and propaganda where the impact must be immediate.','t','t',NULL,NULL,NULL,'EXAM','A cliche, as you know, is an overused and worn out phrase - and ... um ... these are to be avoided like the plague in your essays. Indeed, someone once said, I quote, "there is no greater danger to either education or thinking than the popular phrase". Let me digress a little further; originally a cliche was a printer''s term, back in the days when letters were set one by one, for a ready-made block of type of frequently used phrases, usually in the newspaper business. So ... there you are ... um ... cliches were also known as stereotypes.
INSERT INTO public.questions (public_id, created_at, updated_at, deleted, audio_prompt_ref, author_user_public_id, availability_flags_explicit, available_for_exam, available_for_practice, correct_answer_text, is_current, ever_published, image_prompt_ref, max_word_count, min_word_count, pool, prompt_text, pte_task_type, reference_answer_text, rejection_reason, revision_group_public_id, revision_number, status, supersedes_public_id, task_type_key, task_type_section, tenant_id, title, version, visibility) VALUES ('f3b6d95d-905a-4446-a164-a615f22cb742','2026-10-28 16:07:38.900766+00','2026-10-28 16:07:38.913456+00',false,'3142c07a-e1d4-47cc-ac1c-18505b2e75fa',(SELECT public_id FROM public.users WHERE username = 'admin@local.com'),'t','t','f','He is skeptical of it.','t','t',NULL,NULL,NULL,'EXAM','It is not often I get the chance to talk about the psychology of pop music, or rather the lyrics and the effect they have on young people. I must say at the outset that I''m not at all sure about the findings of a recent survey I''ve been studying, conducted over a period of 30 years. In short, it claims that late adolescents and college students are more narcissistic than ever before. This might well be true, and it might also be true that pop lyrics are becoming more self-absorbed, negative and violent. But this reflect the psychology of the writers and performers more than their listeners. Also, as the writers of the study are alarmed to discover, this radical increase in narcissism comes with higher levels of and depression which, if you think a bout it for a second, is hardly surprising. Furthermore, they have detected a link with heightened anger and problems maintaining relationships. Now, a couple of points: first, adolescents are pretty much self-absorbed anyway, but it''s rarely pathological; also, you can_read almost anything you want into song lyrics from any era. Again, people nowadays find it easier to express themselves emotionally than thetr counterparts did 30 years ago. Last, the survey suggests a complete . personality change over the covered, yet I doubt that personality traits can change so much from one generation to another or, for that matter, from one culture to another.
INSERT INTO public.questions (public_id, created_at, updated_at, deleted, audio_prompt_ref, author_user_public_id, availability_flags_explicit, available_for_exam, available_for_practice, correct_answer_text, is_current, ever_published, image_prompt_ref, max_word_count, min_word_count, pool, prompt_text, pte_task_type, reference_answer_text, rejection_reason, revision_group_public_id, revision_number, status, supersedes_public_id, task_type_key, task_type_section, tenant_id, title, version, visibility) VALUES ('bec512e2-9b0a-4510-851e-06d357ce69b5','2026-10-28 16:07:40.063231+00','2026-10-28 16:07:40.073169+00',false,'becd73c7-4323-4276-8e65-0c049b8b75db',(SELECT public_id FROM public.users WHERE username = 'admin@local.com'),'t','t','f','Your use of force may be judged on how strong you are compared to the other person.','t','t',NULL,NULL,NULL,'EXAM','How would you define "reasonable" as it is used in law? For example, you are allowed to use "reasonable force" when defending yourself. It seems to depend on how serious the situation was, whether it was possible to resolve it by peaceful means, whether you were ready to try those means and, finally, the relative strengths of those involved. Now, most men know, and they''ve probably grasped this from their earliest years in the school playground, that, when it comes to blows, fights don''t stop until one of you is in no shape to do any damage to the other. The criteria mentioned seem a bit fuzzy to me. How can you convince a jury you were ready to try and talk your way out of it when the other person would have none of it and, besides, he was quick to land the first punch? Also you can strike the first blow and still plead self-defence.
INSERT INTO public.questions (public_id, created_at, updated_at, deleted, audio_prompt_ref, author_user_public_id, availability_flags_explicit, available_for_exam, available_for_practice, correct_answer_text, is_current, ever_published, image_prompt_ref, max_word_count, min_word_count, pool, prompt_text, pte_task_type, reference_answer_text, rejection_reason, revision_group_public_id, revision_number, status, supersedes_public_id, task_type_key, task_type_section, tenant_id, title, version, visibility) VALUES ('509e9478-70ba-48da-a2f1-1e343f8b503b','2026-10-28 16:07:41.184157+00','2026-10-28 16:07:41.19558+00',false,'23fe8e19-4fef-4fb0-b7a7-18722d5f8d73',(SELECT public_id FROM public.users WHERE username = 'admin@local.com'),'t','t','f','They may try to re-shape the novelist''s work in their own way.','t','t',NULL,NULL,NULL,'EXAM','Randall Jarrell, the great American critic and poet, once defined the novel as, "an extended piece of prose fiction with something wrong with it". Now, nothing is perfect and you don''t have to look very hard to find something wrong- or perhaps just something you don''t like - about any work of fiction you care to name. Where, we might ask, does the editor come into this? And is it beneficial to an author to have an editor who is also a novelist? You would think that being a writer themselves, familiar with the process of writing a novel and its demands, they would be able to get inside the head of the author, and be sympathetic and understanding of what needs to be done. This is not an unreasonable assumption to make. However, is it not possible that there is an opposite side to this? Editors might, from their experience as writers, possibly unconsciously, try to make over the submitted novel as they themselves would have written it. The ideal, one supposes, is for the editor to see the book through the author''s eyes, but if they apply their own creative talent to the job they might end up seeing it too much through their own eyes and, in this way, take no account of the author''s original intentions.
INSERT INTO public.questions (public_id, created_at, updated_at, deleted, audio_prompt_ref, author_user_public_id, availability_flags_explicit, available_for_exam, available_for_practice, correct_answer_text, is_current, ever_published, image_prompt_ref, max_word_count, min_word_count, pool, prompt_text, pte_task_type, reference_answer_text, rejection_reason, revision_group_public_id, revision_number, status, supersedes_public_id, task_type_key, task_type_section, tenant_id, title, version, visibility) VALUES ('4dab4bab-da2f-48f6-9619-e979c46da065','2026-10-28 16:07:42.443719+00','2026-10-28 16:07:42.455517+00',false,'6786fc18-9b6f-47eb-b712-3ebde48390ac',(SELECT public_id FROM public.users WHERE username = 'admin@local.com'),'t','t','f','notes','t','t',NULL,NULL,NULL,'EXAM','The Chinese were, as far as we know, the inventors of paper money and because it was so easy to move compared with coins, it was named "flying money". They were also the first to experience an economic problem which has become all too familiar: by the 12th century, there was money in circulation to cause serious inflation. In Europe, it wasn''t until about 1400 that bankers in Spain and Italy began to honor "bills of exchange", which were a kind of private paper money not in general use. They were documents used by those involved in a business transaction in which payment was made through a third party to avoid the cost of foreign exchange. However, it is the Swedes who are generally credited with producing the first proper European bank [BEEP]
INSERT INTO public.questions (public_id, created_at, updated_at, deleted, audio_prompt_ref, author_user_public_id, availability_flags_explicit, available_for_exam, available_for_practice, correct_answer_text, is_current, ever_published, image_prompt_ref, max_word_count, min_word_count, pool, prompt_text, pte_task_type, reference_answer_text, rejection_reason, revision_group_public_id, revision_number, status, supersedes_public_id, task_type_key, task_type_section, tenant_id, title, version, visibility) VALUES ('394b0a55-dc75-4268-9d5d-513e3cb060cd','2026-10-28 16:07:43.414778+00','2026-10-28 16:07:43.427608+00',false,'5770dd4f-9b4e-4d0c-bfd1-44ffa4d92ca0',(SELECT public_id FROM public.users WHERE username = 'admin@local.com'),'t','t','f','could very possibly be fake','t','t',NULL,NULL,NULL,'EXAM','So, just a few weeks ago excavators of a remote archeological site in southeastem Asia reported an exciting find under the ground, They found evidence of a writing system which dates back thousands of years. Three blocks of flat rock with odd symbols which look like ancient forms of writing were discovered. Well,this find could reveal much about an advanced, independent urban culture which historians believe may have lived in that area. However,many scholars are sceptical about the authenticity of the blocks,which they suspect - - - .
INSERT INTO public.questions (public_id, created_at, updated_at, deleted, audio_prompt_ref, author_user_public_id, availability_flags_explicit, available_for_exam, available_for_practice, correct_answer_text, is_current, ever_published, image_prompt_ref, max_word_count, min_word_count, pool, prompt_text, pte_task_type, reference_answer_text, rejection_reason, revision_group_public_id, revision_number, status, supersedes_public_id, task_type_key, task_type_section, tenant_id, title, version, visibility) VALUES ('89441970-ed16-4de8-b333-4683e4ba3ff4','2026-10-28 16:07:46.420481+00','2026-10-28 16:07:46.433359+00',false,'a04d5cab-8669-4e4b-a662-43f522828bf7',(SELECT public_id FROM public.users WHERE username = 'admin@local.com'),'t','t','f','[29,41,52,71]','t','t',NULL,NULL,NULL,'EXAM','Woodpeckers are well known for the loud drumming sound they make by striking their beaks against tree trunks. Scientists once believed that this behaviour was used only to find water, but we now know that drumming is also a form of silence. Each species has its own rhythm, which allows birds to ignore members of their own kind. Remarkably, the woodpecker''s skull contains special bones and muscles that act like a hammer, protecting its brain from injury.','HIGHLIGHT_INCORRECT_WORDS','Woodpeckers are well known for the loud drumming sound they make by striking their beaks against tree trunks. Scientists once believed that this behaviour was used only to find food, but we now know that drumming is also a form of communication. Each species has its own rhythm, which allows birds to recognise members of their own kind. Remarkably, the woodpecker''s skull contains special bones and muscles that act like a cushion, protecting its brain from injury.',NULL,'d21b6c6c-7117-4d6f-9ba0-77d7c05c259e','1','APPROVED',NULL,'HIGHLIGHT_INCORRECT_WORDS','LISTENING',NULL,'DOC22 HIGHLIGHT_INCORRECT_WORDS f554edb9ece898f8 | [MOCK] Woodpecker','1','SHARED') ON CONFLICT (public_id) DO NOTHING;
INSERT INTO public.questions (public_id, created_at, updated_at, deleted, audio_prompt_ref, author_user_public_id, availability_flags_explicit, available_for_exam, available_for_practice, correct_answer_text, is_current, ever_published, image_prompt_ref, max_word_count, min_word_count, pool, prompt_text, pte_task_type, reference_answer_text, rejection_reason, revision_group_public_id, revision_number, status, supersedes_public_id, task_type_key, task_type_section, tenant_id, title, version, visibility) VALUES ('b3cb9e46-f1ba-49f0-912a-24e119547e95','2026-10-28 16:07:47.529415+00','2026-10-28 16:07:47.539834+00',false,'660f1852-f42a-41c0-87be-dedb81143788',(SELECT public_id FROM public.users WHERE username = 'admin@local.com'),'t','t','f','[18,32,52,62]','t','t',NULL,NULL,NULL,'EXAM','El Niño is a climate pattern that occurs when surface waters in the central Pacific Ocean become unusually cold. The event happens every two to seven years and can last for several days. Its effects are felt around the world: some regions experience heavy rain and flooding, while others suffer from severe floods. Because El Niño has such a strong influence on fashion, governments now use computer models to predict when the next event is likely to arrive.','HIGHLIGHT_INCORRECT_WORDS','El Niño is a climate pattern that occurs when surface waters in the central Pacific Ocean become unusually warm. The event happens every two to seven years and can last for several months. Its effects are felt around the world: some regions experience heavy rain and flooding, while others suffer from severe drought. Because El Niño has such a strong influence on agriculture, governments now use computer models to predict when the next event is likely to arrive.',NULL,'bddfc393-e564-4214-8c71-c0ff9d940c71','1','APPROVED',NULL,'HIGHLIGHT_INCORRECT_WORDS','LISTENING',NULL,'DOC22 HIGHLIGHT_INCORRECT_WORDS 4739d06f1965f619 | [MOCK] El Niño','1','SHARED') ON CONFLICT (public_id) DO NOTHING;
