INSERT INTO public.questions (public_id, created_at, updated_at, deleted, audio_prompt_ref, author_user_public_id, availability_flags_explicit, available_for_exam, available_for_practice, correct_answer_text, is_current, ever_published, image_prompt_ref, max_word_count, min_word_count, pool, prompt_text, pte_task_type, reference_answer_text, rejection_reason, revision_group_public_id, revision_number, status, supersedes_public_id, task_type_key, task_type_section, tenant_id, title, version, visibility) VALUES ('5684955a-fe2e-49a0-848d-0503fbffb7ee','2026-10-31 03:22:02.188371+00','2026-10-31 03:22:16.918365+00',false,NULL,(SELECT public_id FROM public.users WHERE username = 'admin@local.com'),'t','f','t',NULL,'t','t','acb5126a-cdec-4264-8356-272ad251edbd',NULL,NULL,'PRACTICE',NULL,'DESCRIBE_IMAGE','The following graph gives information about heights of trees.The items include hemlock, cedar, spruce, Douglas fir.According to this graph, in Hemlock, the height is around 130 feet, and that of Cedar is higher, which is around 200 feet.You can see from this graph that the greatest value of height is in Douglas Fir, around 280 feet.To sum up, the graph tells about different heights of trees.',NULL,'07cdd401-a7f9-42a3-a5a7-208af2887b6e','1','APPROVED',NULL,'DESCRIBE_IMAGE','SPEAKING',NULL,'DOC22 DESCRIBE_IMAGE b52d62b0436aa8fa | [MOCK] Height of Tree','2','SHARED') ON CONFLICT (public_id) DO NOTHING;
INSERT INTO public.questions (public_id, created_at, updated_at, deleted, audio_prompt_ref, author_user_public_id, availability_flags_explicit, available_for_exam, available_for_practice, correct_answer_text, is_current, ever_published, image_prompt_ref, max_word_count, min_word_count, pool, prompt_text, pte_task_type, reference_answer_text, rejection_reason, revision_group_public_id, revision_number, status, supersedes_public_id, task_type_key, task_type_section, tenant_id, title, version, visibility) VALUES ('fb44ffb6-8fc5-4af0-98fa-0655da49dd10','2026-10-31 03:28:25.90988+00','2026-10-31 03:28:34.530076+00',false,'f500e065-1537-46eb-8af8-3ebcd7361386',(SELECT public_id FROM public.users WHERE username = 'admin@local.com'),'t','f','t','Last autumn holiday, my family decided to take a trip to a peaceful mountain village in Sa Pa. We wanted to escape the noisy city to enjoy the fresh mountain air and calm environment.','t','t',NULL,NULL,NULL,'PRACTICE','Repeat this sentence based on audio','REPEAT_SENTENCE','Last autumn holiday, my family decided to take a trip to a peaceful mountain village in Sa Pa. We wanted to escape the noisy city to enjoy the fresh mountain air and calm environment.',NULL,'3234c031-16da-48c4-99dd-dee737f42914','1','APPROVED',NULL,'REPEAT_SENTENCE','SPEAKING',NULL,'Repeat Sentence 31/10/2026','2','SHARED') ON CONFLICT (public_id) DO NOTHING;
INSERT INTO public.questions (public_id, created_at, updated_at, deleted, audio_prompt_ref, author_user_public_id, availability_flags_explicit, available_for_exam, available_for_practice, correct_answer_text, is_current, ever_published, image_prompt_ref, max_word_count, min_word_count, pool, prompt_text, pte_task_type, reference_answer_text, rejection_reason, revision_group_public_id, revision_number, status, supersedes_public_id, task_type_key, task_type_section, tenant_id, title, version, visibility) VALUES ('f4262fab-777a-46b9-b423-4e8cddcbc7f2','2026-10-31 03:32:48.123249+00','2026-10-31 03:33:07.117987+00',false,NULL,(SELECT public_id FROM public.users WHERE username = 'admin@local.com'),'t','f','t',NULL,'t','t',NULL,'400','200','PRACTICE','“The only thing that interferes with my learning is education.” – Albert Einstein. What did he mean by that? Do you think he is correct?','WRITE_ESSAY','Einstein was highlighting the friction between natural, self-driven curiosity and the rigid, standardized structures of formal schooling. By "education," he meant the institutional machine: rote memorization, strict curriculums, and studying exclusively to pass exams. "Learning," by contrast, is the organic pursuit of knowledge through experimentation, failure, and genuine interest. He felt that the demands of the educational system often stifle the creative problem-solving required for true intellectual breakthroughs.  There is a profound truth to his observation, particularly in fields that demand constant adaptation and complex system design. A university syllabus provides a necessary foundational roadmap, but it can restrict exploration if the focus shifts entirely to optimizing for a grade or a standardized metric. Genuine learning usually happens the moment you step outside the assigned coursework to build something real on your own terms. Whether that means restructuring a backend into a modular monolith, diving into post-quantum cryptography, or exploring new frameworks just to see how they behave in production, the friction Einstein described tends to disappear when you transition from a passive student into an active creator. The formal system sets the baseline, but true mastery is almost always self-taught.',NULL,'1a124f97-d0e5-4003-8846-90694a2c9bea','1','APPROVED',NULL,'WRITE_ESSAY','WRITING',NULL,'Write Essay 31/10/2026','2','SHARED') ON CONFLICT (public_id) DO NOTHING;
INSERT INTO public.questions (public_id, created_at, updated_at, deleted, audio_prompt_ref, author_user_public_id, availability_flags_explicit, available_for_exam, available_for_practice, correct_answer_text, is_current, ever_published, image_prompt_ref, max_word_count, min_word_count, pool, prompt_text, pte_task_type, reference_answer_text, rejection_reason, revision_group_public_id, revision_number, status, supersedes_public_id, task_type_key, task_type_section, tenant_id, title, version, visibility) VALUES ('0fdb7bc1-0d59-4aaf-a01b-e337edf6be86','2026-10-31 03:37:54.966422+00','2026-10-31 03:38:03.179729+00',false,'9d5b2974-6389-406e-af27-d644c8291301',(SELECT public_id FROM public.users WHERE username = 'admin@local.com'),'t','f','t','[18,32,52,62]','t','t',NULL,NULL,NULL,'PRACTICE','El Niño is a climate pattern that occurs when surface waters in the central Pacific Ocean become unusually cold. The event happens every two to seven years and can last for several months. Its effects are felt around the world: some regions experience heavy rain and flooding, while others suffer from severe drought. Because El Niño has such a strong influence on weather, governments now use computer models to predict when the next event is likely to arrive.','HIGHLIGHT_INCORRECT_WORDS','El Niño is a climate pattern that occurs when surface waters in the central Pacific Ocean become unusually warm. The event happens every two to seven years and can last for several months. Its effects are felt around the world: some regions experience heavy rain and flooding, while others suffer from severe drought. Because El Niño has such a strong influence on agriculture, governments now use computer models to predict when the next event is likely to arrive.',NULL,'e58007ba-f9a7-4f7f-ac70-35888a45a2b4','1','APPROVED',NULL,'HIGHLIGHT_INCORRECT_WORDS','LISTENING',NULL,'Highlight Incorrect Words 31/10/2026','2','SHARED') ON CONFLICT (public_id) DO NOTHING;
INSERT INTO public.questions (public_id, created_at, updated_at, deleted, audio_prompt_ref, author_user_public_id, availability_flags_explicit, available_for_exam, available_for_practice, correct_answer_text, is_current, ever_published, image_prompt_ref, max_word_count, min_word_count, pool, prompt_text, pte_task_type, reference_answer_text, rejection_reason, revision_group_public_id, revision_number, status, supersedes_public_id, task_type_key, task_type_section, tenant_id, title, version, visibility) VALUES ('a95a8034-1abe-402b-a305-47ecc09e06ea','2026-10-31 03:41:36.234+00','2026-10-31 03:41:47.317064+00',false,NULL,(SELECT public_id FROM public.users WHERE username = 'admin@local.com'),'t','f','t','1.recruits, 2.remained, 3.aspect, 4.limit, 5.varied','t','t',NULL,NULL,NULL,'PRACTICE','Thea Proctor was just sixteen when her entry at the Bowral Art Competition caught the eye of the judge, Arthur Streeton. It was the first of many associations with art world {{1}} . The next year saw her at the Julian Ashton Art School in the illustrious company of Elioth Gruner, Sydney Long and George Lambert, for whom she often posed and who {{2}} her great friend until his death in 1930. Lambert''s paintings and sketches of Proctor emphasize the elegance of her dress. A keen interest in fashion was just one {{3}} of her fascination with design, and she saw herself as an early style guru on a quest to rid Australian art of "its lack of imagination and inventive design". Skilled in watercolor and drawing, Proctor did not {{4}} herself to paper, canvases or to her popular magazine illustrations; she designed theater sets and a restaurant interior and wrote on a range of subjects from flower arranging to the colors of cars. It made for a busy and {{5}} life but, as she said, she was not the sort of person "who could sit at home and knit socks."','FILL_IN_THE_BLANKS_DRAG_AND_DROP',NULL,NULL,'61b572e4-80c7-4a34-870b-c203b6cae276','1','APPROVED',NULL,'FILL_IN_THE_BLANKS_DRAG_AND_DROP','READING',NULL,'Fill in the Blanks - Drag and Drop 31/10/2026','2','SHARED') ON CONFLICT (public_id) DO NOTHING;
