INSERT INTO public.question_options (question_id, blank_index, correct, correct_gap_index, order_index, public_id, text) SELECT q.id, NULL, 'f', NULL, '3', 'd558b14b-1c10-40b5-8919-8ac633199718', 'destruction of the carvings because of religion' FROM public.questions q WHERE q.public_id = 'e278486a-39b5-4bc2-8148-2a9c26c675f0' AND NOT EXISTS (SELECT 1 FROM public.question_options o WHERE o.public_id = 'd558b14b-1c10-40b5-8919-8ac633199718');
INSERT INTO public.question_options (question_id, blank_index, correct, correct_gap_index, order_index, public_id, text) SELECT q.id, NULL, 't', NULL, '4', '43c746d2-cf30-42c3-8c07-cf6514e334f0', 'problems caused by insects' FROM public.questions q WHERE q.public_id = 'e278486a-39b5-4bc2-8148-2a9c26c675f0' AND NOT EXISTS (SELECT 1 FROM public.question_options o WHERE o.public_id = '43c746d2-cf30-42c3-8c07-cf6514e334f0');
INSERT INTO public.question_options (question_id, blank_index, correct, correct_gap_index, order_index, public_id, text) SELECT q.id, NULL, 'f', NULL, '0', 'df3a4448-e351-475c-93ad-01b75921b297', 'The speaker talks about the use of memory in Proust''s novel In Search of Lost Time and how memories are usually brought about by the taste or smell of something, in this case, a biscuit dipped in tea. So, it is the senses that provoke memories that can take us back to our childhood.' FROM public.questions q WHERE q.public_id = '45229951-8e59-4417-bb96-640d20d1a1dd' AND NOT EXISTS (SELECT 1 FROM public.question_options o WHERE o.public_id = 'df3a4448-e351-475c-93ad-01b75921b297');
INSERT INTO public.question_options (question_id, blank_index, correct, correct_gap_index, order_index, public_id, text) SELECT q.id, NULL, 'f', NULL, '1', 'c9f4f7cf-45fc-4d04-9a67-b6e574005bd3', 'Using the writer Proust as an example, the speaker tells us how long-term memory works before going on to talk about short-term memory. Distant memories are usually involuntary and are brought to mind by something that stimulates one of the senses. Short-term memory also requires sensory input, but it lasts only a fraction of a second.' FROM public.questions q WHERE q.public_id = '45229951-8e59-4417-bb96-640d20d1a1dd' AND NOT EXISTS (SELECT 1 FROM public.question_options o WHERE o.public_id = 'c9f4f7cf-45fc-4d04-9a67-b6e574005bd3');
INSERT INTO public.question_options (question_id, blank_index, correct, correct_gap_index, order_index, public_id, text) SELECT q.id, NULL, 't', NULL, '2', '23f47962-c60b-4623-b50b-85a5275c2fd5', 'What we experience is processed by the brain into memories in three stages. First, there is the sensory input, which is momentary. This is then stored in the short-term memory. If this experience is important or meaningful to us, we will reinforce the memory, possibly by repetition, and it will then be stored in the long-term memory.' FROM public.questions q WHERE q.public_id = '45229951-8e59-4417-bb96-640d20d1a1dd' AND NOT EXISTS (SELECT 1 FROM public.question_options o WHERE o.public_id = '23f47962-c60b-4623-b50b-85a5275c2fd5');
