INSERT INTO public.question_options (question_id, blank_index, correct, correct_gap_index, order_index, public_id, text) SELECT q.id, NULL, 'f', NULL, '1', '2126aa5e-0135-46ad-9819-9fdc6d8505c9', 'Another example of an endothermic reaction is seen with the cold packs used by athletes to treat injuries. These packs usually consist of a plastic bag containing ammonium nitrate dissolves in the water.' FROM public.questions q WHERE q.public_id = 'aff5740c-8475-48a4-a306-3ac33f3b14ea' AND NOT EXISTS (SELECT 1 FROM public.question_options o WHERE o.public_id = '2126aa5e-0135-46ad-9819-9fdc6d8505c9');
INSERT INTO public.question_options (question_id, blank_index, correct, correct_gap_index, order_index, public_id, text) SELECT q.id, NULL, 'f', NULL, '2', 'c49d0463-0ee3-4224-8a48-c76770893b4f', 'When it is mixed with water in your mouth, an endothermic reaction occurs, taking heat energy from your mouth and making it feel cooler.' FROM public.questions q WHERE q.public_id = 'aff5740c-8475-48a4-a306-3ac33f3b14ea' AND NOT EXISTS (SELECT 1 FROM public.question_options o WHERE o.public_id = 'c49d0463-0ee3-4224-8a48-c76770893b4f');
INSERT INTO public.question_options (question_id, blank_index, correct, correct_gap_index, order_index, public_id, text) SELECT q.id, NULL, 'f', NULL, '3', 'be4cb4de-b9b8-4347-9703-d33ea37562e0', 'A reaction that needs some type of energy to make it go is said to be endothermic. It takes in energy.' FROM public.questions q WHERE q.public_id = 'aff5740c-8475-48a4-a306-3ac33f3b14ea' AND NOT EXISTS (SELECT 1 FROM public.question_options o WHERE o.public_id = 'be4cb4de-b9b8-4347-9703-d33ea37562e0');
INSERT INTO public.question_options (question_id, blank_index, correct, correct_gap_index, order_index, public_id, text) SELECT q.id, NULL, 'f', NULL, '4', '1277cea4-7789-48a7-af5f-5aeb9cb2e7dc', 'This process is endothermic-taking heat energy from the surroundings and cooling the injured part of your body. In this way, the cold pack acts as an ice pack.' FROM public.questions q WHERE q.public_id = 'aff5740c-8475-48a4-a306-3ac33f3b14ea' AND NOT EXISTS (SELECT 1 FROM public.question_options o WHERE o.public_id = '1277cea4-7789-48a7-af5f-5aeb9cb2e7dc');
INSERT INTO public.question_options (question_id, blank_index, correct, correct_gap_index, order_index, public_id, text) SELECT q.id, NULL, 'f', NULL, '0', '8aaef8dc-c34c-45f0-94a7-2dbd5be448fe', 'The topic you choose should be supported by a range of sources.' FROM public.questions q WHERE q.public_id = '948c062d-cf2c-4b37-945a-b751607e8544' AND NOT EXISTS (SELECT 1 FROM public.question_options o WHERE o.public_id = '8aaef8dc-c34c-45f0-94a7-2dbd5be448fe');
INSERT INTO public.question_options (question_id, blank_index, correct, correct_gap_index, order_index, public_id, text) SELECT q.id, NULL, 'f', NULL, '1', 'fcc96147-4b77-4194-be1e-f825231ba5d7', 'The source should be cited under APA guidelines, and the final draft should be written in APA styles.' FROM public.questions q WHERE q.public_id = '948c062d-cf2c-4b37-945a-b751607e8544' AND NOT EXISTS (SELECT 1 FROM public.question_options o WHERE o.public_id = 'fcc96147-4b77-4194-be1e-f825231ba5d7');
INSERT INTO public.question_options (question_id, blank_index, correct, correct_gap_index, order_index, public_id, text) SELECT q.id, NULL, 'f', NULL, '2', 'cfcaf099-4416-4052-999e-4f9217040c0d', 'The final draft is due one week before the final exam.' FROM public.questions q WHERE q.public_id = '948c062d-cf2c-4b37-945a-b751607e8544' AND NOT EXISTS (SELECT 1 FROM public.question_options o WHERE o.public_id = 'cfcaf099-4416-4052-999e-4f9217040c0d');
INSERT INTO public.question_options (question_id, blank_index, correct, correct_gap_index, order_index, public_id, text) SELECT q.id, NULL, 'f', NULL, '3', 'd5c37643-f3ed-4718-8a5a-e7e9b6026a79', 'A requirement of Humanities 104 is to write a persuasive paper on a topic of your choice.' FROM public.questions q WHERE q.public_id = '948c062d-cf2c-4b37-945a-b751607e8544' AND NOT EXISTS (SELECT 1 FROM public.question_options o WHERE o.public_id = 'd5c37643-f3ed-4718-8a5a-e7e9b6026a79');
INSERT INTO public.question_options (question_id, blank_index, correct, correct_gap_index, order_index, public_id, text) SELECT q.id, NULL, 'f', NULL, '0', '8a41f850-61ef-4af3-851d-8fec9907ef7e', 'A Technology for recording brainwaves in wild animals awakens a more sophisticated understanding of the function of sleep.' FROM public.questions q WHERE q.public_id = '228e40da-2d2b-4d56-a064-344de08be76c' AND NOT EXISTS (SELECT 1 FROM public.question_options o WHERE o.public_id = '8a41f850-61ef-4af3-851d-8fec9907ef7e');
INSERT INTO public.question_options (question_id, blank_index, correct, correct_gap_index, order_index, public_id, text) SELECT q.id, NULL, 'f', NULL, '1', '49c5f41f-d881-4e6f-af25-f4e9fdc195e1', 'Studies using miniature sleep recording devices known as neurologgers have already challenged several long-held beliefs about the sleeping habits of sloths and birds.' FROM public.questions q WHERE q.public_id = '228e40da-2d2b-4d56-a064-344de08be76c' AND NOT EXISTS (SELECT 1 FROM public.question_options o WHERE o.public_id = '49c5f41f-d881-4e6f-af25-f4e9fdc195e1');
INSERT INTO public.question_options (question_id, blank_index, correct, correct_gap_index, order_index, public_id, text) SELECT q.id, NULL, 'f', NULL, '2', '5809e3b7-be0c-4f28-9d76-ac69abf6974d', 'And male sandpipers can go almost entirely without sleep during the three-week breeding season, helping maximize success at that time.' FROM public.questions q WHERE q.public_id = '228e40da-2d2b-4d56-a064-344de08be76c' AND NOT EXISTS (SELECT 1 FROM public.question_options o WHERE o.public_id = '5809e3b7-be0c-4f28-9d76-ac69abf6974d');
INSERT INTO public.question_options (question_id, blank_index, correct, correct_gap_index, order_index, public_id, text) SELECT q.id, NULL, 'f', NULL, '3', 'cd0c9d30-e0b2-4b73-a55c-996f3b3bcb3c', 'Three toed sloths, for example, sleep far less than once thought.' FROM public.questions q WHERE q.public_id = '228e40da-2d2b-4d56-a064-344de08be76c' AND NOT EXISTS (SELECT 1 FROM public.question_options o WHERE o.public_id = 'cd0c9d30-e0b2-4b73-a55c-996f3b3bcb3c');
