INSERT INTO public.question_options (question_id, blank_index, correct, correct_gap_index, order_index, public_id, text) SELECT q.id, NULL, 't', NULL, '3', 'af640d74-af14-4573-8db0-641b1a0d6dd7', 'how long the building is likely to last' FROM public.questions q WHERE q.public_id = '26c136be-aac4-4add-9779-fe6a9f720039' AND NOT EXISTS (SELECT 1 FROM public.question_options o WHERE o.public_id = 'af640d74-af14-4573-8db0-641b1a0d6dd7');
INSERT INTO public.question_options (question_id, blank_index, correct, correct_gap_index, order_index, public_id, text) SELECT q.id, NULL, 'f', NULL, '4', '88256a63-579c-49d3-a7ca-9072fdf564ea', 'how well the building suits its purpose' FROM public.questions q WHERE q.public_id = '26c136be-aac4-4add-9779-fe6a9f720039' AND NOT EXISTS (SELECT 1 FROM public.question_options o WHERE o.public_id = '88256a63-579c-49d3-a7ca-9072fdf564ea');
INSERT INTO public.question_options (question_id, blank_index, correct, correct_gap_index, order_index, public_id, text) SELECT q.id, NULL, 't', NULL, '0', '20f49719-94af-440a-b998-ff6312bdb060', 'Dolphins, whales and porpoises are all social animals, but some species are more sociable than others. This depends on the environment because a species adopts the lifestyle most suitable for this. Among dolphins, forming groups makes it easier for them to find food, reproduce and gain knowledge. They are safer, too, because dolphins can communicate danger when there are threats around.' FROM public.questions q WHERE q.public_id = 'f76b6029-68e9-492b-a08c-6eabd2f05b62' AND NOT EXISTS (SELECT 1 FROM public.question_options o WHERE o.public_id = '20f49719-94af-440a-b998-ff6312bdb060');
INSERT INTO public.question_options (question_id, blank_index, correct, correct_gap_index, order_index, public_id, text) SELECT q.id, NULL, 'f', NULL, '1', '7b700751-5552-4ab6-8867-5f106fdf7889', 'The speaker explains that whales, dolphins, and porpoises have evolved differently and face different threats. River dolphin numbers are declining, while ocean dolphins are doing well in spite of the threats they face. The reason for this is that ocean dolphins are better adapted for finding food and avoiding predators.' FROM public.questions q WHERE q.public_id = 'f76b6029-68e9-492b-a08c-6eabd2f05b62' AND NOT EXISTS (SELECT 1 FROM public.question_options o WHERE o.public_id = '7b700751-5552-4ab6-8867-5f106fdf7889');
INSERT INTO public.question_options (question_id, blank_index, correct, correct_gap_index, order_index, public_id, text) SELECT q.id, NULL, 'f', NULL, '2', 'b5c766b2-7cca-4fd3-8afe-b2ab2bfca540', 'Dolphins have adopted group living as a response to living in close contact with other animals in the ocean, some of which kill dolphins for food. Living in social groups makes it easier to hunt for food and, in a dangerous environment, it makes sense in terms of safety to move about in large numbers.' FROM public.questions q WHERE q.public_id = 'f76b6029-68e9-492b-a08c-6eabd2f05b62' AND NOT EXISTS (SELECT 1 FROM public.question_options o WHERE o.public_id = 'b5c766b2-7cca-4fd3-8afe-b2ab2bfca540');
INSERT INTO public.question_options (question_id, blank_index, correct, correct_gap_index, order_index, public_id, text) SELECT q.id, NULL, 't', NULL, '0', '9f5b93d8-3ef4-4e9f-b64e-32820ec2e45b', 'Men form societies to better cope with the dangers in life.' FROM public.questions q WHERE q.public_id = 'aef2c4c1-c0ea-43eb-a076-7f3f8bbe15ae' AND NOT EXISTS (SELECT 1 FROM public.question_options o WHERE o.public_id = '9f5b93d8-3ef4-4e9f-b64e-32820ec2e45b');
INSERT INTO public.question_options (question_id, blank_index, correct, correct_gap_index, order_index, public_id, text) SELECT q.id, NULL, 'f', NULL, '1', '5644da92-e971-4131-acc4-69f5516c3250', 'Society has a corrupting influence on people.' FROM public.questions q WHERE q.public_id = 'aef2c4c1-c0ea-43eb-a076-7f3f8bbe15ae' AND NOT EXISTS (SELECT 1 FROM public.question_options o WHERE o.public_id = '5644da92-e971-4131-acc4-69f5516c3250');
INSERT INTO public.question_options (question_id, blank_index, correct, correct_gap_index, order_index, public_id, text) SELECT q.id, NULL, 'f', NULL, '2', 'eff0e52d-3053-4ac8-ada1-77fe7f87be86', 'People were far happier in a "state of nature" before civilization.' FROM public.questions q WHERE q.public_id = 'aef2c4c1-c0ea-43eb-a076-7f3f8bbe15ae' AND NOT EXISTS (SELECT 1 FROM public.question_options o WHERE o.public_id = 'eff0e52d-3053-4ac8-ada1-77fe7f87be86');
INSERT INTO public.question_options (question_id, blank_index, correct, correct_gap_index, order_index, public_id, text) SELECT q.id, NULL, 't', NULL, '3', 'dba7b36c-dc58-4134-a374-52eba06af846', 'By forming societies, law and morality come into force.' FROM public.questions q WHERE q.public_id = 'aef2c4c1-c0ea-43eb-a076-7f3f8bbe15ae' AND NOT EXISTS (SELECT 1 FROM public.question_options o WHERE o.public_id = 'dba7b36c-dc58-4134-a374-52eba06af846');
INSERT INTO public.question_options (question_id, blank_index, correct, correct_gap_index, order_index, public_id, text) SELECT q.id, NULL, 'f', NULL, '4', 'a86914d2-feb1-4d28-afbb-2d09edc14ed1', 'Children''s emotions should be educated before their intellect.' FROM public.questions q WHERE q.public_id = 'aef2c4c1-c0ea-43eb-a076-7f3f8bbe15ae' AND NOT EXISTS (SELECT 1 FROM public.question_options o WHERE o.public_id = 'a86914d2-feb1-4d28-afbb-2d09edc14ed1');
INSERT INTO public.question_options (question_id, blank_index, correct, correct_gap_index, order_index, public_id, text) SELECT q.id, NULL, 'f', NULL, '0', '6d4162e8-87ac-4fb1-b344-664be8e8d447', 'Cliches are the enemy of literature and art. They are words, phrases and images that have become stale through overuse and therefore have nothing new to say to us. They are an enemy to clear and original thinking, although they are sometimes useful in advertising to get a simple message across.' FROM public.questions q WHERE q.public_id = 'aae76d49-fa1b-41b7-a3c5-9acb3c660b2b' AND NOT EXISTS (SELECT 1 FROM public.question_options o WHERE o.public_id = '6d4162e8-87ac-4fb1-b344-664be8e8d447');
INSERT INTO public.question_options (question_id, blank_index, correct, correct_gap_index, order_index, public_id, text) SELECT q.id, NULL, 't', NULL, '1', 'fee09614-18fc-42e9-9332-cd3604da0b50', 'While cliches in writing reveal lazy thinking and are to be avoided at all costs, in the graphic arts they become essential, helping to get the message across quickly, clearly and with emotional force. This is especially true of advertising and propaganda where the impact must be immediate.' FROM public.questions q WHERE q.public_id = 'aae76d49-fa1b-41b7-a3c5-9acb3c660b2b' AND NOT EXISTS (SELECT 1 FROM public.question_options o WHERE o.public_id = 'fee09614-18fc-42e9-9332-cd3604da0b50');
INSERT INTO public.question_options (question_id, blank_index, correct, correct_gap_index, order_index, public_id, text) SELECT q.id, NULL, 'f', NULL, '2', '7d1186df-f5e3-4e7a-b70a-1829b1082721', 'Cliches are worn out, overused and over-familiar phrases, and the etymology of the word helps to explain this. Originally, a cliche or stereotype was a printer''s term for a pre-set block of type with phrases used frequently in the newspapers. The word has since adopted a negative meaning and careful writers avoid them where they can.' FROM public.questions q WHERE q.public_id = 'aae76d49-fa1b-41b7-a3c5-9acb3c660b2b' AND NOT EXISTS (SELECT 1 FROM public.question_options o WHERE o.public_id = '7d1186df-f5e3-4e7a-b70a-1829b1082721');
INSERT INTO public.question_options (question_id, blank_index, correct, correct_gap_index, order_index, public_id, text) SELECT q.id, NULL, 'f', NULL, '3', 'ff7129c7-3ade-4d67-97b3-8d0a287a4111', 'Cliches, whether in language or graphic design, are entirely worthless and should be eliminated in all fields. In literature, they destroy original thinking, and in graphic arts, they only create confusion instead of conveying clear messages.' FROM public.questions q WHERE q.public_id = 'aae76d49-fa1b-41b7-a3c5-9acb3c660b2b' AND NOT EXISTS (SELECT 1 FROM public.question_options o WHERE o.public_id = 'ff7129c7-3ade-4d67-97b3-8d0a287a4111');
INSERT INTO public.question_options (question_id, blank_index, correct, correct_gap_index, order_index, public_id, text) SELECT q.id, NULL, 'f', NULL, '0', '029acada-4adb-4f9d-aa36-b402141d6186', 'He is amused by it.' FROM public.questions q WHERE q.public_id = 'f3b6d95d-905a-4446-a164-a615f22cb742' AND NOT EXISTS (SELECT 1 FROM public.question_options o WHERE o.public_id = '029acada-4adb-4f9d-aa36-b402141d6186');
